pub mod model_banks {include!("diagnostics.rs");}
include!("summary.rs");
#[test] fn all_support_and_trace_combinations_preserve_unknown(){use model_banks::ModelBankDiagnostics as D; let traces=[None,Some(D::default()),Some(D{geometry_candidates:7,pixel_geometry_refusals:7,pixel_rejections:0}),Some(D{geometry_candidates:7,pixel_geometry_refusals:0,pixel_rejections:7})];let mut count=0;for a in [None,Some(false),Some(true)]{for b in [None,Some(false),Some(true)]{for am in [false,true]{for bm in [false,true]{for at in traces {for bt in traces {let e=NativeBankConsensusEvidence{forward:NativeBankDirectionSummary{support:a,model_attempted:am,model_diagnostics:at},reverse:NativeBankDirectionSummary{support:b,model_attempted:bm,model_diagnostics:bt}};assert_eq!(e.supported(),if a==Some(true)&&b==Some(true){Some(true)}else{None});assert_eq!(e.forward.model_diagnostics,at);assert_eq!(e.reverse.model_diagnostics,bt);count+=1;}}}}}}assert_eq!(count,576);}
